    throw std::runtime_error("Gadgetron::clear(): Invalid input array");

  if ( x->get_number_of_elements() > 0 )
  {
    cudaMemset(x->get_data_ptr(),0,sizeof(T)*x->get_number_of_elements());
  }
}

